// backend\src\controllers\paymentController.js
// controllers/paymentController.js
import { paymentService } from '../services/paymentService.js';
import { paymobProvider } from '../services/providers/paymob.js';
import Payment from '../models/Payment.js';

function ownerKindFromReq(req) {
  return req.actor.account.role === 'patient' ? 'patient' : 'doctor';
}   

export const paymentController = {
  // POST /billing/checkout   { planId, billingCycle }
  async subscriptionCheckout(req, res, next) {
    try {
      const { planId, billingCycle = 'monthly' } = req.body;
      if (!planId) return res.status(400).json({ status: 'error', message: 'planId is required' });
      if (!['monthly', 'yearly'].includes(billingCycle)) {
        return res.status(400).json({ status: 'error', message: 'billingCycle must be monthly or yearly' });
      }

      const result = await paymentService.startSubscriptionCheckout({
        orgId: req.params.orgId,
        planId,
        billingCycle,
        actor: req.actor,
      });
      res.json({ data: result });
    } catch (err) { next(err); }
  },

  // POST /wallets/me/topup   { amount }   (replaces the old direct-credit topup)
  async walletTopup(req, res, next) {
    try {
      const amount = Number(req.body.amount);
      if (!amount || amount <= 0 || amount > 50_000) {
        return res.status(400).json({ status: 'error', message: 'Amount must be between 1 and 50,000 EGP' });
      }
      const result = await paymentService.startWalletTopup({
        accountId: req.actor.account._id,
        ownerKind: ownerKindFromReq(req),
        amount,
        actor:     req.actor,
      });
      res.json({ data: result });
    } catch (err) { next(err); }
  },

  // POST /organizations/:orgId/wallet/topup   { amount }
  async orgWalletTopup(req, res, next) {
    try {
      const amount = Number(req.body.amount);
      if (!amount || amount <= 0 || amount > 500_000) {
        return res.status(400).json({ status: 'error', message: 'Amount must be between 1 and 500,000 EGP' });
      }
      const result = await paymentService.startOrgWalletTopup({
        orgId:  req.params.orgId,
        amount,
        actor:  req.actor,
      });
      res.json({ data: result });
    } catch (err) { next(err); }
  },

  // GET /payments/result?paymentId=...    (frontend lands here after checkout)
  async result(req, res, next) {
    try {
      const payment = await Payment.findById(req.query.paymentId);
      if (!payment) return res.status(404).json({ status: 'error', message: 'Payment not found' });
      res.json({
        data: {
          status:      payment.status,
          purpose:     payment.purpose,
          amountCents: payment.amountCents,
          currency:    payment.currency,
        },
      });
    } catch (err) { next(err); }
  },

  // POST /webhooks/paymob   (public — Paymob authenticates via HMAC)
  async paymobWebhook(req, res, next) {
    try {
      const obj  = req.body?.obj;
      const hmac = req.query.hmac || req.body?.hmac;

      if (!obj) return res.status(400).send('Missing obj');
      if (!paymobProvider.verifyHmac(obj, hmac)) {
        return res.status(401).send('Invalid HMAC');
      }

      await paymentService.handleWebhook(obj);
      // Paymob only cares about a 2xx response — reply fast.
      res.sendStatus(200);
    } catch (err) {
      // Log the failure but still 200 to prevent Paymob from retrying forever
      // during dev. Adjust if you'd rather have retries.
      console.error('[Paymob webhook] Error:', err);
      res.sendStatus(200);
    }
  },
};


// backend\src\controllers\transactionController.js
import mongoose from 'mongoose';
import Transaction from '../models/Transaction.js';

export const transactionController = {
  async list(req, res) {
    const { orgId } = req.params;
    const { branchId, status, from, to, limit = 50, page = 1 } = req.query;

    const query = { org: new mongoose.Types.ObjectId(orgId) };
    if (branchId) query.branch = new mongoose.Types.ObjectId(branchId);
    if (status)   query.status = status;
    if (from || to) {
      query.createdAt = {};
      if (from) query.createdAt.$gte = new Date(from);
      if (to)   query.createdAt.$lte = new Date(`${to}T23:59:59.999Z`);
    }

    const skip = (Number(page) - 1) * Number(limit);
    const [transactions, total] = await Promise.all([
      Transaction.find(query)
        .sort({ createdAt: -1 })
        .skip(skip)
        .limit(Number(limit))
        .populate('branch', 'name')
        .lean(),
      Transaction.countDocuments(query),
    ]);

    res.json({ data: { transactions, total, page: Number(page), limit: Number(limit) } });
  },

  async summary(req, res) {
    const { orgId } = req.params;
    const orgObjectId = new mongoose.Types.ObjectId(orgId);
    const now = new Date();
    const monthStart = new Date(now.getFullYear(), now.getMonth(), 1);

    const [allTime, thisMonth] = await Promise.all([
      Transaction.aggregate([
        { $match: { org: orgObjectId } },
        {
          $group: {
            _id: null,
            totalEarnings: { $sum: '$commissionAmount' },
            pendingAmount: {
              $sum: { $cond: [{ $eq: ['$status', 'pending'] }, '$commissionAmount', 0] },
            },
          },
        },
      ]),
      Transaction.aggregate([
        { $match: { org: orgObjectId, createdAt: { $gte: monthStart } } },
        { $group: { _id: null, thisMonthEarnings: { $sum: '$commissionAmount' } } },
      ]),
    ]);

    res.json({
      data: {
        totalEarnings:      allTime[0]?.totalEarnings      ?? 0,
        pendingAmount:      allTime[0]?.pendingAmount       ?? 0,
        thisMonthEarnings:  thisMonth[0]?.thisMonthEarnings ?? 0,
        currency:           'EGP',
      },
    });
  },
};


// backend\src\controllers\walletController.js
import { walletService } from '../services/walletService.js';
import Wallet from '../models/Wallet.js';
import { Membership } from '../models/Membership.js';
import Appointment from '../models/Appointment.js';

/**
 * Resolve the personal wallet for the authenticated user.
 * For patients ownerKind = 'patient'; for staff/doctors ownerKind = 'doctor'.
 * Uses req.actor set by the authenticate middleware (not req.user).
 */
function ownerKindFromReq(req) {
  return req.actor.account.role === 'patient' ? 'patient' : 'doctor';
}

export const walletController = {
  // ── Personal wallet (patient / doctor) ──────────────────────────────────────

  async getMyWallet(req, res, next) {
    try {
      const wallet = await walletService.getOrCreateAccountWallet(
        req.actor.account._id,
        ownerKindFromReq(req),
      );
      res.json({ data: { wallet: serializeWallet(wallet) } });
    } catch (err) { next(err); }
  },

  async topUp(req, res, next) {
    try {
      const amount = Number(req.body.amount);
      if (!amount || amount <= 0 || amount > 50_000) {
        return res.status(400).json({ status: 'error', message: 'Amount must be between 1 and 50,000 EGP' });
      }
      const wallet = await walletService.topUp({
        accountId: req.actor.account._id,
        ownerKind: ownerKindFromReq(req),
        amount,
      });
      res.json({ data: { wallet: serializeWallet(wallet) } });
    } catch (err) { next(err); }
  },

  async purchaseAtBooking(req, res, next) {
    try {
      const accountId = req.actor.account._id;
      const { appointmentId, amount } = req.body;

      if (!appointmentId) return res.status(400).json({ status: 'error', message: 'appointmentId is required' });
      const fee = Number(amount);
      if (!fee || fee <= 0) return res.status(400).json({ status: 'error', message: 'Invalid amount' });

      // Verify the appointment belongs to this patient's profile
      const appointment = await Appointment.findById(appointmentId).populate('patientProfile', 'accountId').lean();
      if (!appointment) return res.status(404).json({ status: 'error', message: 'Appointment not found' });
      if (String(appointment.patientProfile?.accountId) !== String(accountId)) {
        return res.status(403).json({ status: 'error', message: 'Appointment does not belong to this user' });
      }
      // Guard against double-charging — idempotency check
      if (appointment.paymentStatus === 'success') {
        return res.status(409).json({ status: 'error', message: 'Appointment has already been paid' });
      }

      const wallet = await walletService.purchaseDebit({ accountId, amount: fee, appointmentId });

      // Mark appointment as prepaid via wallet so queueService skips the auto-debit at completion
      await Appointment.findByIdAndUpdate(appointmentId, {
        $set: { paymentMethod: 'wallet', paymentStatus: 'success' },
      });

      res.json({ status: 'ok', data: { wallet: serializeWallet(wallet) } });
    } catch (err) {
      next(err);
    }
  },

  async requestWithdrawal(req, res, next) {
    try {
      const amount      = Number(req.body.amount);
      const destination = String(req.body.destination ?? '').trim();
      if (!amount || amount < 100 || amount > 100_000) {
        return res.status(400).json({ status: 'error', message: 'Amount must be between 100 and 100,000 EGP' });
      }
      if (!destination || destination.length < 5) {
        return res.status(400).json({ status: 'error', message: 'Destination (bank account or mobile number) is required' });
      }
      const wallet = await walletService.withdraw({
        accountId: req.actor.account._id,
        ownerKind: ownerKindFromReq(req),
        amount,
        destination,
      });
      res.json({ data: { wallet: serializeWallet(wallet) } });
    } catch (err) { next(err); }
  },

  async getMyEntries(req, res, next) {
    try {
      const { limit = 50, page = 1 } = req.query;
      const wallet = await walletService.getOrCreateAccountWallet(
        req.actor.account._id,
        ownerKindFromReq(req),
      );
      const { entries, total } = await walletService.getEntries({ walletId: wallet._id, limit, page });
      res.json({ data: { entries: entries.map(serializeEntry), total, page: Number(page), limit: Number(limit) } });
    } catch (err) { next(err); }
  },

  // ── Organization wallet (admin only) ────────────────────────────────────────

  async getOrgWallet(req, res) {
    const wallet = await walletService.getOrCreateOrgWallet(req.params.orgId);
    res.json({ data: { wallet: serializeWallet(wallet) } });
  },

  async topUpOrg(req, res) {
    const amount = Number(req.body.amount);
    if (!amount || amount <= 0 || amount > 500_000) {
      return res.status(400).json({ status: 'error', message: 'Amount must be between 1 and 500,000 EGP' });
    }
    const wallet = await walletService.orgTopUp({ orgId: req.params.orgId, amount });
    res.json({ data: { wallet: serializeWallet(wallet) } });
  },

  async getOrgEntries(req, res) {
    const { limit = 50, page = 1 } = req.query;
    const wallet = await walletService.getOrCreateOrgWallet(req.params.orgId);
    const { entries, total } = await walletService.getEntries({ walletId: wallet._id, limit, page });
    res.json({ data: { entries: entries.map(serializeEntry), total, page: Number(page), limit: Number(limit) } });
  },
};

function serializeWallet(w) {
  return {
    id:           String(w._id),
    balance:      w.balance,
    currency:     w.currency,
    ownerKind:    w.ownerKind,
    status:       w.status,
    updatedAt:    w.updatedAt,
  };
}

function serializeEntry(e) {
  return {
    id:            String(e._id),
    type:          e.type,
    direction:     e.direction,
    amount:        e.amount,
    balanceAfter:  e.balanceAfter,
    description:   e.description,
    status:        e.status,
    createdAt:     e.createdAt,
    referenceKind: e.referenceKind,
  };
}


