// backend\src\services\providers\paymob.js
import crypto from 'node:crypto';
import { env } from '../../config/env.js';
import { AppError } from '../../utils/errors.js';

/**
 * Paymob provider (MVP) — Intention API flow.
 *
 *   1. createIntention()  → returns a checkout URL to redirect the user to
 *   2. verifyHmac()       → validates the webhook Paymob sends after payment
 */

export const paymobProvider = {
  async createIntention({ amountCents, currency, merchantOrderId, billingData, items }) {
    // Dev stub — no creds, no calls.
    if (!env.paymob?.secretKey) {
      console.log('[Paymob stub] Would create intention:', { amountCents, currency, merchantOrderId });
      return { checkoutUrl: `https://example.test/checkout?ref=${merchantOrderId}`, stub: true };
    }

    const res = await fetch(`${env.paymob.baseUrl}/v1/intention/`, {
      method: 'POST',
      headers: {
        'Content-Type':  'application/json',
        'Authorization': `Token ${env.paymob.secretKey}`,
      },
      body: JSON.stringify({
        amount:            amountCents,
        currency,
        payment_methods:   [env.paymob.integrationId], // one method is enough for MVP
        items,
        billing_data:      billingData,
        special_reference: merchantOrderId,
        notification_url:  env.paymob.notificationUrl,
        redirection_url:   env.paymob.redirectionUrl,
      }),
      signal: AbortSignal.timeout(10_000),
    });

    const data = await res.json();
    if (!res.ok) throw new AppError(data?.detail || 'Paymob error', res.status, 'PAYMOB_ERROR');

    const checkoutUrl =
      `${env.paymob.baseUrl}/unifiedcheckout/` +
      `?publicKey=${env.paymob.publicKey}&clientSecret=${data.client_secret}`;

    return { checkoutUrl, intentionId: data.id };
  },

  /**
   * Verify the HMAC Paymob sends with every webhook.
   * The 20 fields below MUST be concatenated in this exact order.
   */
  verifyHmac(obj, providedHmac) {
    if (!env.paymob?.hmacSecret || !providedHmac) return false;

    const fields = [
      'amount_cents', 'created_at', 'currency', 'error_occured',
      'has_parent_transaction', 'id', 'integration_id', 'is_3d_secure',
      'is_auth', 'is_capture', 'is_refunded', 'is_standalone_payment',
      'is_voided', 'order.id', 'owner', 'pending',
      'source_data.pan', 'source_data.sub_type', 'source_data.type', 'success',
    ];

    const signedString = fields
      .map(path => path.split('.').reduce((o, k) => o?.[k], obj) ?? '')
      .join('');

    const expected = crypto
      .createHmac('sha512', env.paymob.hmacSecret)
      .update(signedString)
      .digest('hex');

    return expected === String(providedHmac);
  },
};


// backend\src\services\appointmentService.js
import Appointment from '../models/Appointment.js';
import Session from '../models/QueueSession.js';
import { patientService } from './patientService.js';
import { queueService } from './queueService.js';
import { walletService } from './walletService.js';
import { generateToken } from '../utils/otp.js';
import { AppError, Conflict, Forbidden, NotFound } from '../utils/errors.js';

const CANCELLATION_PENALTY_EGP = 50;
const CANCELLATION_GRACE_MS    = 60 * 60 * 1000; // 1 hour

const TERMINAL_STATUSES = ['completed', 'cancelled', 'no_show'];

export const appointmentService = {
  async bookWalkIn({ actor, sessionId, branchId, orgId, data }) {
    // Receptionist must be assigned to this branch
    if (actor.activeMembership?.kind === 'receptionist') {
      const assigned = (actor.activeMembership.branches || []).map(String);
      if (!assigned.includes(String(branchId))) {
        throw Forbidden('Receptionist is not authorized for this branch');
      }
    }

    const session = await Session.findOne({
      _id:    sessionId,
      branch: branchId,
      status: { $in: ['scheduled', 'active'] },
    }).populate('doctor');
    if (!session) throw NotFound('Session not found or not accepting bookings');

    // Enforce capacity if set
    if (session.maxBookings != null && session.bookingsCount >= session.maxBookings) {
      throw new AppError('Session is at full capacity', 409);
    }

    const profile = await patientService.findOrCreateWalkIn({
      orgId,
      branchId,
      phone:    data.patientPhone,
      fullName: data.patientName,
    });

    const updated = await Session.reserveQueueNumber(sessionId);
    if (!updated) throw new AppError('Session is no longer accepting bookings', 409);

    const queueNumber = updated.bookingsCount;
    const accessToken = generateToken(16);

    let appointment;
    try {
      appointment = await Appointment.create({
        session:          session._id,
        patientProfile:   profile._id,
        organization:     orgId,
        branch:           branchId,
        doctorMembership: session.doctor,
        queueNumber,
        status:           'booked',
        source:           'walk_in',
        bookedBy:         actor.activeMembership._id,
        accessToken,
        notes:            data.notes,
        appointmentType:  data.appointmentType ?? 'new_consultation',
      });
    } catch (err) {
      if (err.code === 11000) throw Conflict('Patient already has an active booking in this session');
      throw err;
    }

    // Simple positional EWT shown to receptionist at booking time
    const position        = Math.max(0, queueNumber - (updated.currentServing ?? 0));
    const estimatedWaitMin = position * (updated.avgConsultationMin ?? 15)
      + (updated.globalDelayMin ?? 0);

    return { appointment, accessToken, estimatedWaitMin };
  },

  async bookOverride({ actor, sessionId, branchId, orgId, data }) {
    if (actor.activeMembership?.kind !== 'admin') {
      throw Forbidden('Only admins can create override bookings');
    }

    const session = await Session.findOne({
      _id:    sessionId,
      branch: branchId,
      status: { $in: ['scheduled', 'active'] },
    }).populate('doctor');
    if (!session) throw NotFound('Session not found');

    const profile = await patientService.findOrCreateWalkIn({
      orgId,
      branchId,
      phone:    data.patientPhone,
      fullName: data.patientName,
    });

    // Override: use $inc regardless of maxBookings
    const updated = await Session.findOneAndUpdate(
      { _id: sessionId },
      { $inc: { bookingsCount: 1 } },
      { new: true }
    );
    if (!updated) throw NotFound('Session not found');

    const queueNumber = updated.bookingsCount;
    const accessToken = generateToken(16);

    let appointment;
    try {
      appointment = await Appointment.create({
        session:          session._id,
        patientProfile:   profile._id,
        organization:     orgId,
        branch:           branchId,
        doctorMembership: session.doctor,
        queueNumber,
        status:           'booked',
        source:           'override',
        bookedBy:         actor.activeMembership._id,
        accessToken,
        notes:            data.notes,
      });
    } catch (err) {
      if (err.code === 11000) throw Conflict('Patient already has an active booking in this session');
      throw err;
    }

    return { appointment, accessToken };
  },
}


