Here's the patched `result` handler with ownership verification:

```js
// controllers/paymentController.js

// GET /billing/result?paymentId=...
async result(req, res, next) {
  try {
    const { paymentId } = req.query;
    if (!paymentId) {
      return res.status(400).json({ status: 'error', message: 'paymentId is required' });
    }

    // Validate the id format up front — avoids a CastError leaking as 500
    if (!mongoose.isValidObjectId(paymentId)) {
      return res.status(400).json({ status: 'error', message: 'Invalid paymentId' });
    }

    const payment = await Payment.findById(paymentId).lean();
    if (!payment) {
      return res.status(404).json({ status: 'error', message: 'Payment not found' });
    }

    if (!isPaymentOwner(payment, req.actor)) {
      // Return 404 (not 403) so we don't confirm the existence of a payment
      // that belongs to someone else — prevents payment-id enumeration.
      return res.status(404).json({ status: 'error', message: 'Payment not found' });
    }

    res.json({
      data: {
        id:          String(payment._id),
        status:      payment.status,
        purpose:     payment.purpose,
        amountCents: payment.amountCents,
        currency:    payment.currency,
        processedAt: payment.processedAt,
        failureReason: payment.status === 'failed' ? payment.failureReason : undefined,
      },
    });
  } catch (err) { next(err); }
},
```

And the helper (place at the top of the file, next to `ownerKindFromReq`):

```js
import mongoose from 'mongoose';

/**
 * A payment is visible to:
 *   - the account that initiated it (appointment payments)
 *   - any active admin of the organization it belongs to
 *     (subscription + org wallet top-up)
 *   - platform admins
 */
function isPaymentOwner(payment, actor) {
  if (!actor?.account?._id) return false;
  if (actor.isPlatformAdmin) return true;

  // Account-owned payment (appointment)
  if (payment.account && String(payment.account) === String(actor.account._id)) {
    return true;
  }

  // Organization-owned payment (subscription, org_wallet_topup)
  if (payment.organization) {
    const sameOrg = actor.activeOrgId
      && String(actor.activeOrgId) === String(payment.organization);
    const isAdmin = actor.activeMembership?.kind === 'admin';
    if (sameOrg && isAdmin) return true;
  }

  return false;
}
```

### Why these specific rules

| Payment purpose | `payment.account` | `payment.organization` | Who may view |
|---|---|---|---|
| `appointment` | patient's account id | `null` | that patient only |
| `subscription` | `null` | org id | admins of that org |
| `org_wallet_topup` | `null` | org id | admins of that org |

The check matches the shape of `Payment` after your model patch (no more `wallet_topup`, no `ownerKind` for individuals). It's also **membership-tenant-aware**: an admin who has switched into a *different* org (`activeOrgId`) cannot read a former org's payments even if they still have a membership record there — because `authorize`/`activeMembership` are keyed off `activeOrgId`.

### Two subtle choices worth flagging

1. **404 instead of 403 on unauthorized access.** Returning 403 tells an attacker "this id exists, but not for you", which lets them enumerate valid payment ids. Returning 404 makes existence indistinguishable from non-existence.

2. **Don't leak `failureReason` on success.** The raw Paymob error string can contain provider internals; only expose it when the payment actually failed.

### Route reminder

Keep the route as-is — the middleware chain already ensures `req.actor` is populated:

```js
