```js
import Wallet from '../models/Wallet.js';
import WalletEntry from '../models/WalletEntry.js';

/**
 * Find or create the wallet for an organization.
 * Atomic upsert prevents race-condition duplicates.
 */
async function getOrCreateOrgWallet(orgId) {
  return Wallet.findOneAndUpdate(
    { organization: orgId },
    { $setOnInsert: { organization: orgId, balance: 0, status: 'active', currency: 'EGP' } },
    { upsert: true, new: true },
  );
}

/**
 * Atomically debit a wallet. Returns the updated wallet doc.
 * Throws if the wallet is frozen/closed or has insufficient funds.
 */
async function debitWallet(walletId, amount, entryMeta) {
  const wallet = await Wallet.findOneAndUpdate(
    { _id: walletId, status: 'active', balance: { $gte: amount } },
    { $inc: { balance: -amount } },
    { new: true },
  );
  if (!wallet) {
    const w = await Wallet.findById(walletId);
    if (!w || w.status !== 'active') throw new Error('Wallet is frozen or closed');
    throw new Error('Insufficient wallet balance');
  }
  await WalletEntry.create({
    wallet:       wallet._id,
    direction:    'debit',
    amount,
    balanceAfter: wallet.balance,
    status:       'settled',
    ...entryMeta,
  });
  return wallet;
}

async function creditWallet(walletId, amount, entryMeta) {
  const wallet = await Wallet.findByIdAndUpdate(
    walletId,
    { $inc: { balance: amount } },
    { new: true },
  );
  if (!wallet) throw new Error(`Wallet ${walletId} not found`);
  await WalletEntry.create({
    wallet:       wallet._id,
    direction:    'credit',
    amount,
    balanceAfter: wallet.balance,
    status:       'settled',
    ...entryMeta,
  });
  return wallet;
}

export const walletService = {
  getOrCreateOrgWallet,
  debitWallet,
  creditWallet,

  /**
   * Credit an organization's wallet with its commission share of an appointment.
   * Called only from the appointment settlement path (queueService / paymentService).
   */
  async orgCommissionCredit({ orgId, amount, appointmentId }) {
    const wallet = await getOrCreateOrgWallet(orgId);
    return creditWallet(wallet._id, amount, {
      type:          'commission',
      reference:     appointmentId,
      referenceKind: 'appointment',
      description:   'Organization commission share',
    });
  },

  /**
   * Debit the organization wallet for a subscription plan purchase.
   * Called from orgService.purchasePlan when balance is sufficient.
   */
  async planPurchaseDebit({ orgId, amount, planId, planName }) {
    const wallet = await getOrCreateOrgWallet(orgId);
    return debitWallet(wallet._id, amount, {
      type:          'plan_purchase',
      reference:     planId,
      referenceKind: 'plan',
      description:   `Plan subscription: ${planName}`,
    });
  },

  async getEntries({ walletId, limit = 50, page = 1 }) {
    const skip = (Number(page) - 1) * Number(limit);
    const [entries, total] = await Promise.all([
      WalletEntry.find({ wallet: walletId })
        .sort({ createdAt: -1 })
        .skip(skip)
        .limit(Number(limit))
        .lean(),
      WalletEntry.countDocuments({ wallet: walletId }),
    ]);
    return { entries, total };
  },
};
```

### `services/paymentService.js` — rewritten

```js
import Payment from '../models/Payment.js';
import SubscriptionPlan from '../models/SubscriptionPlan.js';
import Appointment from '../models/Appointment.js';
import { paymobProvider } from './providers/paymob.js';
import { subscriptionService } from './subscriptionService.js';
import { AppError, NotFound, Forbidden, Conflict } from '../utils/errors.js';

function billingFromAccount(account) {
  return {
    first_name:   account.fullName?.split(' ')[0]                 || 'NA',
    last_name:    account.fullName?.split(' ').slice(1).join(' ') || 'NA',
    email:        account.email || 'na@example.com',
    phone_number: account.phone || 'NA',
    country: 'EGY', city: 'NA', street: 'NA',
    building: 'NA', floor: 'NA', apartment: 'NA',
  };
}

export const paymentService = {
  // ── Checkout starters ───────────────────────────────────────────────────

  async startSubscriptionCheckout({ orgId, planId, billingCycle, actor }) {
    const plan = await SubscriptionPlan.findById(planId);
    if (!plan || !plan.isActive) throw NotFound('Plan not found');

    const monthly = plan.priceMonthly;
    const amount  = billingCycle === 'yearly'
      ? Math.round(monthly * 12 * (1 - (plan.yearlyDiscount || 0) / 100))
      : monthly;
    const amountCents = Math.round(amount * 100);

    const payment = await Payment.create({
      purpose:      'subscription',
      organization: orgId,
      plan:         planId,
      billingCycle,
      amountCents,
      currency:     plan.currency || 'EGP',
    });

    const { checkoutUrl, intentionId } = await paymobProvider.createIntention({
      amountCents,
      currency:        plan.currency || 'EGP',
      merchantOrderId: String(payment._id),
      billingData:     billingFromAccount(actor.account),
      items: [{
        name:     `${plan.name} (${billingCycle})`,
        amount:   amountCents,
        quantity: 1,
      }],
    });

    if (intentionId) {
      payment.paymobIntentionId = String(intentionId);
      await payment.save();
    }

    return { checkoutUrl, paymentId: payment._id };
  },

  async startAppointmentCheckout({ appointmentId, actor }) {
    const appointment = await Appointment.findById(appointmentId)
      .populate('patientProfile', 'accountId')
      .populate('session', 'consultationFee currency');
    if (!appointment) throw NotFound('Appointment not found');

    // Ownership: patient can only pay for their own appointments
    if (String(appointment.patientProfile?.accountId) !== String(actor.account._id)) {
      throw Forbidden('Appointment does not belong to this user');
    }

    // Idempotency
    if (appointment.paymentStatus === 'success') {
      throw Conflict('Appointment is already paid');
    }
    if (['completed', 'cancelled', 'no_show'].includes(appointment.status)) {
      throw Conflict(`Cannot pay for an appointment in status "${appointment.status}"`);
    }

    const fee = appointment.session?.consultationFee;
    if (!fee || fee <= 0) throw new AppError('Session has no consultation fee configured', 400);

    const currency    = appointment.session.currency || 'EGP';
    const amountCents = Math.round(fee * 100);

    // If a previous pending payment exists for this appointment, reuse it
    let payment = await Payment.findOne({
      purpose:     'appointment',
      appointment: appointment._id,
      status:      'pending',
    });

    if (!payment) {
      payment = await Payment.create({
        purpose:     'appointment',
        account:     actor.account._id,
        appointment: appointment._id,
        amountCents,
        currency,
      });
    }

    const { checkoutUrl, intentionId } = await paymobProvider.createIntention({
      amountCents,
      currency,
      merchantOrderId: String(payment._id),
      billingData:     billingFromAccount(actor.account),
      items: [{ name: 'Appointment consultation', amount: amountCents, quantity: 1 }],
    });

    if (intentionId) {
      payment.paymobIntentionId = String(intentionId);
      await payment.save();
    }

    return { checkoutUrl, paymentId: payment._id };
  },

  // ── Webhook handler ─────────────────────────────────────────────────────

  async handleWebhook(obj) {
    const merchantOrderId = obj?.order?.merchant_order_id;
    if (!merchantOrderId) throw new AppError('Missing merchant_order_id', 400);

    const payment = await Payment.findById(merchantOrderId);
    if (!payment) throw NotFound('Payment record not found');

    // Idempotency
    if (payment.status === 'success') return { alreadyProcessed: true };

    payment.paymobTransactionId = String(obj.id);
    payment.processedAt         = new Date();

    if (!obj.success || obj.error_occured) {
      payment.status        = 'failed';
      payment.failureReason = obj.data?.message || 'Payment failed';
      await payment.save();

      if (payment.purpose === 'subscription') {
        await subscriptionService.markPastDue(payment.organization);
      }
      return { ok: true, status: 'failed' };
    }

    payment.status = 'success';
    await payment.save();

    switch (payment.purpose) {
      case 'subscription':
        await subscriptionService.activateOrRenew({
          orgId:        payment.organization,
          planId:       payment.plan,
          billingCycle: payment.billingCycle,
          providerRef:  String(obj.id),
        });
        break;

      case 'appointment':
        await Appointment.findByIdAndUpdate(payment.appointment, {
          $set: {
            paymentMethod: 'paymob',
            paymentStatus: 'success',
            paidAt:        new Date(),
          },
        });
        break;
    }

    return { ok: true, status: 'success' };
  },
};
